    int64_t need, keel;
    if (draft_cm <= 0 || margin_pct < 0) return 0;
    need = ((int64_t)draft_cm * margin_pct + 99) / 100;
    keel = (int64_t)depth_cm + height_cm - draft_cm;
    return keel >= need;
}

